# Repara o histórico de migrations local × remoto e aplica as pendentes.
#
# Contexto (25/08/2026): desde 08/07 as migrations foram aplicadas em produção
# via MCP do Supabase, que grava carimbos próprios no histórico remoto, enquanto
# os arquivos locais têm carimbos redondos. Resultado: `npx supabase db push`
# recusa (59 versões remotas órfãs) e 47 locais constam "pendentes" mas JÁ estão
# no schema (verificado por spot-check em 25/08: weekly_ranking.track,
# pets.apelidos, report_card_pending, forum_bans, current_ranking_cycle_start).
#
# Os dois `repair` abaixo só mexem na TABELA DE HISTÓRICO — não executam nenhum
# SQL de migration. O `db push` final aplica apenas o que é novo de verdade
# (ensure_daily_question + trails para todos).
#
# Uso:  powershell -File scripts/reparar-historico-migrations.ps1

# 1. Marca as 47 migrations locais já aplicadas como aplicadas no histórico remoto
npx supabase migration repair --status applied 20260708200000 20260710010000 20260710020000 20260710030000 20260710040000 20260710050000 20260710060000 20260710120000 20260710130000 20260710140000 20260710150000 20260710160000 20260710170000 20260720000000 20260721000000 20260721140000 20260723120000 20260723130000 20260723150000 20260724000000 20260724010000 20260724020000 20260727000000 20260727010000 20260728000000 20260728120000 20260729090000 20260729140000 20260729141000 20260729160000 20260729170000 20260729180000 20260729190000 20260811000000 20260811001000 20260811002000 20260811003000 20260811010000 20260811020000 20260811030000 20260811040000 20260811050000 20260811060000 20260812000000 20260812001000 20260812002000 20260812003000
if (-not $?) { Write-Host 'repair --status applied falhou; parando.' ; exit 1 }

# 2. Remove os 59 carimbos órfãos criados pelo MCP
npx supabase migration repair --status reverted 20260708184250 20260710040349 20260710041414 20260710041558 20260710041651 20260710045819 20260710141930 20260710203709 20260710212401 20260711004949 20260711012648 20260711012946 20260711013331 20260714014805 20260720115210 20260721122630 20260722115921 20260723010033 20260723010844 20260723015045 20260723150501 20260724111733 20260724114038 20260725001957 20260727145251 20260727151717 20260728153808 20260728213709 20260729005332 20260729005414 20260729161531 20260729161656 20260729191725 20260729213003 20260729215525 20260729215632 20260729220945 20260811032545 20260811032644 20260811032735 20260811032814 20260811034215 20260811035514 20260811050520 20260811052538 20260811152559 20260811152722 20260811154023 20260811154432 20260811160058 20260811160419 20260812025129 20260812025616 20260812025708 20260812025756 20260812030443 20260812030500 20260812031303 20260812202252
if (-not $?) { Write-Host 'repair --status reverted falhou; parando.' ; exit 1 }

# 3. Aplica só as migrations novas de verdade
npx supabase db push
